    out = [row[:] for row in grid]

    # Infer the horizontal period from the patterned rows, scoring consistency
    # within each row so that different rows may start at different phases.
    scores = {}
    for p in range(2, 11):
        score = 0
        for r in range(h):
            vals = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
            if len(vals) < 8:
                continue
            buckets = {}
            for c, v in vals:
                buckets.setdefault(c % p, []).append(v)
            score += sum(len(a) - max(a.count(v) for v in set(a))
                         for a in buckets.values())
        scores[p] = score
    period = min(scores, key=lambda p: (scores[p], p))

    for r in range(h):
        row = grid[r]
        c = 0
        while c < w:
            if row[c] != 0:
                c += 1
                continue
            start = c
            while c < w and row[c] == 0:
                c += 1
            end = c
            # Only interpolate zero-runs bounded on both sides by colored cells.
            if start == 0 or end == w:
                continue
            left, right = start - 1, end
            if row[left] == 0 or row[right] == 0:
                continue

            # For each phase, use the most frequent visible color in this row.
            buckets = {}
            for x in range(3, w):
                if row[x] != 0:
                    buckets.setdefault(x % period, []).append(row[x])
            phase_color = {
                phase: max(set(a), key=a.count)
                for phase, a in buckets.items()
            }
            for x in range(start, end):
                color = phase_color.get(x % period)
                if color is not None:
                    out[r][x] = color

    return out
